1	import { readFileSync, existsSync } from "fs";
2	import { join } from "path";
3	import { getDb, getMailDir } from "./db";
4	
5	/**
6	 * Find and read the .emlx file for a given message ROWID.
7	 * Mail.app stores messages as .emlx files in a directory structure based on
8	 * the mailbox URL and message ROWID.
9	 */
10	export function readEmlx(messageRowId: number): string | null {
11	  const mailDir = getMailDir();
12	  const db = getDb();
13	
14	  // Get the mailbox URL for this message
15	  const row = db
16	    .prepare(
17	      `SELECT mb.url FROM messages m
18	       JOIN mailboxes mb ON m.mailbox = mb.ROWID
19	       WHERE m.ROWID = ?`
20	    )
21	    .get(messageRowId) as { url: string } | undefined;
22	
23	  if (!row) return null;
24	
25	  const mailboxPath = mailboxUrlToPath(row.url, mailDir);
26	  if (!mailboxPath) return null;
27	
28	  // Search for the .emlx file - Mail.app uses the message ROWID as filename
29	  const filename = `${messageRowId}.emlx`;
30	  const found = findFile(mailboxPath, filename);
31	  if (!found) return null;
32	
33	  return readFileSync(found, "utf-8");
34	}
35	
36	/**
37	 * Parse an .emlx file into headers and body.
38	 * Format: first line is byte count, then raw RFC 822 message, then Apple plist.
39	 */
40	export function parseEmlx(content: string): {
41	  headers: Record<string, string>;
42	  body: string;
43	  textBody: string;
44	} {
45	  const lines = content.split("\n");
46	  // First line is the byte count of the message portion
47	  const byteCount = parseInt(lines[0], 10);
48	  const messageStart = lines[0].length + 1;
49	  const rawMessage = content.substring(messageStart, messageStart + byteCount);
50	
51	  // Split headers and body
52	  const headerEnd = rawMessage.indexOf("\r\n\r\n");
53	  const splitIdx = headerEnd !== -1 ? headerEnd : rawMessage.indexOf("\n\n");
54	  const headerSection =
55	    splitIdx !== -1 ? rawMessage.substring(0, splitIdx) : rawMessage;
56	  const bodySection =
57	    splitIdx !== -1
58	      ? rawMessage.substring(splitIdx + (headerEnd !== -1 ? 4 : 2))
59	      : "";
60	
61	  const headers: Record<string, string> = {};
62	  let currentKey = "";
63	  for (const line of headerSection.split(/\r?\n/)) {
64	    if (line.match(/^\s/) && currentKey) {
65	      headers[currentKey] += " " + line.trim();
66	    } else {
67	      const colonIdx = line.indexOf(":");
68	      if (colonIdx > 0) {
69	        currentKey = line.substring(0, colonIdx).toLowerCase();
70	        headers[currentKey] = line.substring(colonIdx + 1).trim();
71	      }
72	    }
73	  }
74	
75	  // Extract plain text from body (handle multipart, base64, quoted-printable)
76	  const textBody = extractText(bodySection, headers["content-type"] || "", headers["content-transfer-encoding"] || "");
77	
78	  return { headers, body: bodySection, textBody };
79	}
80	
81	function extractText(
82	  body: string,
83	  contentType: string,
84	  encoding: string
85	): string {
86	  // Handle multipart messages
87	  const boundaryMatch = contentType.match(/boundary="?([^";\s]+)"?/);
88	  if (boundaryMatch) {
89	    const boundary = boundaryMatch[1];
90	    const parts = body.split(`--${boundary}`);
91	    // Find the text/plain part first, fall back to text/html
92	    for (const part of parts) {
93	      if (part.includes("Content-Type: text/plain") || part.includes("content-type: text/plain")) {
94	        const partHeaderEnd = part.indexOf("\r\n\r\n") !== -1 ? part.indexOf("\r\n\r\n") : part.indexOf("\n\n");
95	        if (partHeaderEnd === -1) continue;
96	        const partHeaders = part.substring(0, partHeaderEnd);
97	        const partBody = part.substring(partHeaderEnd + (part.indexOf("\r\n\r\n") !== -1 ? 4 : 2));
98	        const partEncoding = partHeaders.match(/Content-Transfer-Encoding:\s*(\S+)/i)?.[1] || "";
99	        return decodeBody(partBody, partEncoding);
100	      }
101	    }
102	    // Try html part
103	    for (const part of parts) {
104	      if (part.includes("Content-Type: text/html") || part.includes("content-type: text/html")) {
105	        const partHeaderEnd = part.indexOf("\r\n\r\n") !== -1 ? part.indexOf("\r\n\r\n") : part.indexOf("\n\n");
106	        if (partHeaderEnd === -1) continue;
107	        const partHeaders = part.substring(0, partHeaderEnd);
108	        const partBody = part.substring(partHeaderEnd + (part.indexOf("\r\n\r\n") !== -1 ? 4 : 2));
109	        const partEncoding = partHeaders.match(/Content-Transfer-Encoding:\s*(\S+)/i)?.[1] || "";
110	        return stripHtml(decodeBody(partBody, partEncoding));
111	      }
112	    }
113	  }
114	
115	  const decoded = decodeBody(body, encoding);
116	  if (contentType.includes("text/html")) {
117	    return stripHtml(decoded);
118	  }
119	  return decoded;
120	}
121	
122	function decodeBody(body: string, encoding: string): string {
123	  encoding = encoding.toLowerCase().trim();
124	  if (encoding === "base64") {
125	    try {
126	      return Buffer.from(body.replace(/\s/g, ""), "base64").toString("utf-8");
127	    } catch {
128	      return body;
129	    }
130	  }
131	  if (encoding === "quoted-printable") {
132	    return body
133	      .replace(/=\r?\n/g, "")
134	      .replace(/=([0-9A-Fa-f]{2})/g, (_, hex) =>
135	        String.fromCharCode(parseInt(hex, 16))
136	      );
137	  }
138	  return body;
139	}
140	
141	function stripHtml(html: string): string {
142	  return html
143	    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
144	    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
145	    .replace(/<br\s*\/?>/gi, "\n")
146	    .replace(/<\/p>/gi, "\n\n")
